// Returns number of half-stars (1..10) â€” so 5 = 2.5 stars, 10 = 5 stars
function ratingToHalfStars(r) {
  if (r < 40) return 1;
  if (r >= 88) return 10;
  return Math.max(1, Math.min(10, Math.floor((r - 40) / 5.4) + 1));
}
// Legacy compat â€” full-star integer (1..5) used by filter dropdowns
function ratingToStars(r) {
  return Math.ceil(ratingToHalfStars(r) / 2);
}
function starsHTML(r) {
  const half = ratingToHalfStars(r);
  const display = (half / 2).toFixed(1).replace(/\.0$/, '');
  let h = '<span class="stars">';
  for (let i = 0; i < 5; i++) {
    const slot = i * 2;
    if (half >= slot + 2) h += 'â˜…';
    else if (half >= slot + 1) h += '<span class="star-half">â˜…</span>';
    else h += '<span class="star-empty">â˜…</span>';
  }
  h += `<span class="rating-num">${display}/5</span></span>`;
  return h;
}

