function generateCupSchedule() {
  G.cupMatches = [];
  G.cupResults = {};
  const otherTeams = Object.values(G.teams).filter(t => t.id !== G.userTeamId);
  // Define cup ladders â€” each item: { cup, round, week }
  const carabaoSchedule = [
    { cup: "carabao", round: "R1", week: 4 },
    { cup: "carabao", round: "R2", week: 8 },
    { cup: "carabao", round: "R3", week: 12 },
    { cup: "carabao", round: "QF", week: 17 },
    { cup: "carabao", round: "SF", week: 22 },
    { cup: "carabao", round: "FINAL", week: 30 }
  ];
  const faSchedule = [
    { cup: "fa", round: "R3", week: 14 },
    { cup: "fa", round: "R4", week: 19 },
    { cup: "fa", round: "R5", week: 25 },
    { cup: "fa", round: "QF", week: 31 },
    { cup: "fa", round: "SF", week: 38 },
    { cup: "fa", round: "FINAL", week: 45 }
  ];
  // European cups only for Premier League sides
  let euroSchedule = [];
  if (G.division === "Premier League") {
    euroSchedule = [
      { cup: "cl", round: "GS1", week: 5 },
      { cup: "cl", round: "GS2", week: 7 },
      { cup: "cl", round: "GS3", week: 10 },
      { cup: "cl", round: "GS4", week: 15 },
      { cup: "cl", round: "GS5", week: 18 },
      { cup: "cl", round: "GS6", week: 21 },
      { cup: "cl", round: "R16", week: 26 },
      { cup: "cl", round: "QF", week: 32 },
      { cup: "cl", round: "SF", week: 36 },
      { cup: "cl", round: "FINAL", week: 42 }
    ];
  }
  const all = [...carabaoSchedule, ...faSchedule, ...euroSchedule];
  all.forEach(({ cup, round, week }) => {
    const opponent = pick(otherTeams);
    G.cupMatches.push({
      week, cup, round,
      opponentId: opponent.id,
      isHome: Math.random() < 0.5,
      played: false,
      eliminated: false
    });
  });
  G.cupResults = { fa: { status: "in" }, carabao: { status: "in" }, cl: { status: G.division === "Premier League" ? "in" : "n/a" } };
}

